  // Decode binary data on load (takes ~5 ms)
  var rawBytes = null;
  var dataView = null;

  function initBuffer() {
    if (dataView) { return; }
    var binStr = atob(B64_DATA);
    var len = binStr.length;
    var u8 = new Uint8Array(len);
    for (var i = 0; i < len; i += 1) {
      u8[i] = binStr.charCodeAt(i);
    }
    rawBytes = u8;
    dataView = new DataView(u8.buffer);
  }

  // Binary search for closest frame index
  function findFrameIndex(targetFrame) {
    var low = 0;
    var high = FRAMES_LIST.length - 1;
    while (low <= high) {
      var mid = (low + high) >> 1;
      var f = FRAMES_LIST[mid];
      if (f === targetFrame) { return mid; }
      if (f < targetFrame) { low = mid + 1; }
      else { high = mid - 1; }
    }
    if (low >= FRAMES_LIST.length) { return FRAMES_LIST.length - 1; }
    if (high < 0) { return 0; }
    return Math.abs(FRAMES_LIST[low] - targetFrame) < Math.abs(FRAMES_LIST[high] - targetFrame) ? low : high;
  }

  // Decode a single frame at byte offset in 0.001 ms
  function decodeFrameAtOffset(offset) {
    initBuffer();
    var view = dataView;
    var frame = view.getUint32(offset, true);
    var period = view.getUint8(offset + 4);
    var clock_tenths = view.getUint16(offset + 5, true);
    var clock_s = clock_tenths / 10;
    var bx = view.getInt16(offset + 7, true) / 20;
    var by = view.getInt16(offset + 9, true) / 20;
    var bz = view.getInt16(offset + 11, true) / 20;
    var bspd = view.getInt16(offset + 13, true) / 10;
    var possCode = view.getUint8(offset + 15);
    var carrierIdx = view.getUint8(offset + 16);
    var sh = view.getUint8(offset + 17);
    var sa = view.getUint8(offset + 18);
    var numPlayers = view.getUint8(offset + 19);

    var poss = possCode === 1 ? 'home' : (possCode === 2 ? 'away' : null);
    var carrier = (carrierIdx < PLAYERS.length) ? PLAYERS[carrierIdx].id : null;

    var playersList = [];
    var pOffset = offset + 20;
    for (var i = 0; i < numPlayers; i += 1) {
      var pidx = view.getUint8(pOffset);
      var px = view.getInt16(pOffset + 1, true) / 20;
      var py = view.getInt16(pOffset + 3, true) / 20;
      var pspd = view.getInt16(pOffset + 5, true) / 10;
      pOffset += 7;

      if (pidx < PLAYERS.length) {
        var pInfo = PLAYERS[pidx];
        playersList.push({
          id: pInfo.id,
          team: pInfo.team,
          num: pInfo.num,
          role: pInfo.role,
          name: pInfo.name,
          x: px,
          y: py,
          speed: pspd,
          conf: 0.95
        });
      }
    }

    return {
      frame: frame,
      period: period,
      clock_s: clock_s,
      ball: {
        x: bx,
        y: by,
        z: bz,
        speed: bspd,
        airborne: bz > 0.35,
        conf: 0.95
      },
      possession: poss,
      carrier: carrier,
      score: { home: sh, away: sa },
      players: playersList
    };
  }

